export function createManualWhatsAppUI({api,esc,toast,openDialog,closeDialog}) {
 const endpoint='/api/portal/whatsapp-manual';
 let active=false,phone='',data=null,busy=false,epoch=0,poll,draft={text:'',template:'',parameters:[],asset:null,requestId:null},locked=false;
 const date=n=>n?new Date(n).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'';
 const status={sending:'Enviando',accepted:'Aceita pela Meta',sent:'Enviada',delivered:'Entregue',read:'Lida',failed:'Falha no envio',uncertain:'Envio sem confirmação',pending_media:'Baixando anexo',downloading:'Baixando anexo',media_failed:'Falha no anexo',received:'Recebida'};
 const page=()=>'<section class="page-heading"><div><p class="overline">ADMINISTRAÇÃO HELPU</p><h1>Atendimento WhatsApp</h1><p>Converse com interessados e clientes pelo número oficial da Helpu.</p></div></section><div id="wa-manual"><p role="status">Carregando atendimento…</p></div>';
 function history(){return (data.messages||[]).map(m=>`<article class="wa-message ${m.direction==='outgoing'?'outgoing':''}"><strong>${m.direction==='outgoing'?'Equipe Helpu':esc(data.selected.name)}</strong><p>${esc(m.text||(!m.asset?(m.unsupported?'Mensagem recebida em formato não exibido.':'Anexo recebido.') :''))}</p>${m.asset?`<a href="${esc(m.asset.url)}" target="_blank" rel="noopener">Abrir ${esc(m.asset.name)}</a>`:''}<small>${date(m.sentAt||m.createdAt)} · ${status[m.state]||esc(m.state)}</small>${m.error?`<p role="status">${esc(m.error)}</p>`:''}</article>`).join('')||'<p class="wa-empty">As mensagens recebidas durante o atendimento manual e seus envios aparecerão aqui. O histórico anterior do Astra permanece na conversa do cliente.</p>';}
 function contacts(){return data.contacts.map(c=>`<button type="button" data-wa-contact="${esc(c.phone)}" aria-pressed="${c.phone===phone}"><strong>${esc(c.name)}</strong><span>+${esc(c.phone)}</span><small>${c.mode==='manual'?'Atendimento da equipe':'Astra ativo'}</small></button>`).join('')||'<p>Nenhum contato recebido ainda.</p>';}
 function draw(){const el=document.querySelector('#wa-manual');if(!el||!active)return;
  if(!data.enabled){el.innerHTML=`<section class="admin-box"><h2>Uma caixa para o mesmo número</h2><p>Ao ativar, mensagens de pessoas sem vínculo com o Astra chegam à equipe. As conversas já vinculadas continuam com o Astra até você assumir um atendimento.</p><p>Não troca o número, a conexão nem o cadastro na Meta.</p><button class="p-button primary" data-wa="enable">Ativar caixa de atendimento</button></section>`;return;}
  const c=data.selected;
  el.innerHTML=`<div class="wa-toolbar"><p>Número oficial: <strong>${esc(data.officialPhone||'Não configurado')}</strong>${!data.configured?' · Conexão pendente':''}</p><button class="p-button secondary" data-wa="refresh">Atualizar mensagens</button><button class="p-button primary" data-wa="new">Novo contato</button></div><details class="admin-callout"><summary>Boas-vindas no cadastro</summary><p>${data.welcomePersonalized?'Modelo personalizado configurado; o envio depende da aprovação e disponibilidade na Meta.':'A mensagem personalizada está preparada. Falta configurar na hospedagem o novo modelo aprovado pela Meta.'} O envio usa nome e empresa, exige autorização no cadastro e não ativa o Astra automaticamente.</p></details><div class="wa-inbox"><aside class="wa-contacts" aria-label="Contatos">${contacts()}</aside><section class="wa-conversation">${c?`<div class="wa-conversation-head"><h2>${esc(c.name)}</h2><p>+${esc(c.phone)} · ${c.mode==='manual'?'Você está no atendimento':'Astra ativo'} · ${c.insideWindow?'Janela de resposta aberta':'Somente modelo aprovado'}</p>${c.suppressed?'<p role="alert">Este contato pediu para sair. Novos envios estão bloqueados.</p>':''}${c.mode==='manual'?(c.linked?'<button class="p-button secondary" data-wa="resume">Devolver ao Astra</button>':'<p>Para usar o Astra, este contato precisa criar a conta e ativar o WhatsApp no portal.</p>'):'<button class="p-button primary" data-wa="take">Assumir atendimento</button>'}</div><div class="wa-history" role="log" aria-label="Mensagens">${history()}</div><div id="wa-composer"></div>`:'<p class="wa-empty">Selecione um contato ou cadastre um interessado. Não é necessário que ele tenha conta na Helpu.</p>'}</section></div><p class="wa-footnote">Atualização automática a cada 15 segundos. A equipe responde manualmente; nenhum envio em massa é iniciado por esta tela.</p>`;
  composer();
 }
 function composer(){const el=document.querySelector('#wa-composer'),c=data?.selected;if(!el||!c)return;if(c.mode!=='manual'||c.suppressed){el.innerHTML='';return;}
  const t=data.templates.find(t=>t.name===draft.template),can=c.insideWindow||!!t;
  el.innerHTML=`<form id="wa-send"><label class="p-field"><span>Tipo de mensagem</span><select name="template"><option value="">Mensagem livre ${c.insideWindow?'':'(aguarda resposta do contato)'}</option>${data.templates.map(t=>`<option value="${esc(t.name)}" ${t.name===draft.template?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label>${t?`<p class="wa-template">${esc(t.text)}</p>${Array.from({length:t.parameters},(_,i)=>`<label class="p-field"><span>Campo ${i+1} do modelo</span><input data-wa-param="${i}" maxlength="500" required value="${esc(draft.parameters[i]||'')}"></label>`).join('')}`:`<label class="p-field"><span>Mensagem</span><textarea name="text" rows="3" maxlength="4096" ${!c.insideWindow?'disabled':''}>${esc(draft.text)}</textarea></label><label class="p-field"><span>Anexo · JPG, PNG, PDF ou MP4 · até 3 MB</span><input type="file" name="attachment" accept="image/jpeg,image/png,application/pdf,video/mp4" ${!c.insideWindow?'disabled':''}></label><p id="wa-attachment">${draft.asset?esc(draft.asset.name):''}</p>${draft.asset?'<button type="button" class="p-button secondary" data-wa="remove">Remover anexo</button>':''}`}${!c.insideWindow?'<p>Para iniciar ou retomar a conversa, registre a autorização do contato e use um modelo aprovado. A resposta dele libera mensagens livres por 24 horas.</p><button type="button" class="p-button secondary" data-wa="consent">Registrar autorização</button>':''}<button class="p-button primary" type="submit" ${!can||busy||locked||!data.configured?'disabled':''}>Enviar mensagem</button>${locked?'<p role="alert">Envio sem confirmação. Não repita antes de conferir com o contato.</p><button type="button" class="p-button secondary" data-wa="unlock">Conferi o envio; preparar outra mensagem</button>':''}<p>Ao assumir, novas mensagens ficam com você. Pedidos já em produção continuam; as entregas do Astra aguardam a retomada.</p></form>`;
 }
 async function load(quiet=false){const current=++epoch;try{const next=await api(endpoint+(phone?'?phone='+encodeURIComponent(phone):''));if(!active||current!==epoch)return;const previous=data;data=next;if(quiet&&previous&&data.selected?.mode===previous.selected?.mode&&data.selected?.insideWindow===previous.selected?.insideWindow&&data.selected?.suppressed===previous.selected?.suppressed){const h=document.querySelector('.wa-history'),cs=document.querySelector('.wa-contacts');if(h)h.innerHTML=history();if(cs)cs.innerHTML=contacts();}else draw();}catch(e){if(!quiet)toast(e.message,true);}}
 async function act(action,extra={}){return api(endpoint,'POST',{action,phone,...extra});}
 function newContact(consentOnly=false){openDialog(consentOnly?'Autorização do contato':'Novo contato',`<form id="wa-contact-form"><label class="p-field"><span>Nome do contato</span><input name="name" required maxlength="120" value="${esc(consentOnly?data.selected.name:'')}"></label><label class="p-field"><span>WhatsApp com DDD (outro país: use +)</span><input name="phone" required value="${esc(consentOnly?'+'+phone:'')}" ${consentOnly?'readonly':''}></label><label><input type="checkbox" name="consent" ${consentOnly?'required':''}> O contato autorizou receber mensagens da Helpu.</label><label class="p-field"><span>Onde e quando autorizou (necessário para iniciar uma conversa)</span><textarea name="evidence" maxlength="1000" placeholder="Ex.: formulário de interesse, data e pedido do contato"></textarea></label><button class="p-button primary">Salvar contato</button></form>`);}
 document.addEventListener('input',e=>{if(!active)return;if(e.target.closest('#wa-send')){if(e.target.name==='text')draft.text=e.target.value;if(e.target.dataset.waParam!==undefined)draft.parameters[+e.target.dataset.waParam]=e.target.value;}});
 document.addEventListener('change',async e=>{if(!active||!e.target.closest('#wa-send'))return;if(e.target.name==='template'){draft.template=e.target.value;draft.parameters=[];composer();}if(e.target.name==='attachment'&&e.target.files[0]){const file=e.target.files[0];if(file.size>3*1024*1024){toast('Envie arquivo de até 3 MB.',true);e.target.value='';return;}busy=true;const button=document.querySelector('#wa-send button[type=submit]');if(button)button.disabled=true;try{const r=await fetch(endpoint+'/files?phone='+encodeURIComponent(phone),{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});const a=await r.json();if(!r.ok)throw Error(a.error||'Falha no anexo');draft.asset=a;}catch(err){toast(err.message,true);}finally{busy=false;composer();}}});
 document.addEventListener('click',async e=>{if(!active||busy)return;const contact=e.target.closest('[data-wa-contact]'),b=e.target.closest('[data-wa]');if(contact){if(locked||draft.text||draft.asset||draft.parameters.some(Boolean)){toast('Conclua ou limpe a mensagem atual antes de trocar de contato.',true);return;}phone=contact.dataset.waContact;draft={text:'',template:'',parameters:[],asset:null,requestId:null};await load();return;}if(!b)return;const action=b.dataset.wa;if(action==='new'||action==='consent'){newContact(action==='consent');return;}if(action==='refresh'){await load();return;}if(action==='remove'){draft.asset=null;composer();return;}if(action==='unlock'){locked=false;draft.requestId=null;draft.text='';draft.parameters=[];draft.asset=null;composer();return;}if(action==='resume'){openDialog('Retomar o Astra','<p>O Astra volta a receber os próximos pedidos e pode entregar respostas e materiais pendentes. A conversa manual não será reenviada como pedido de criação.</p><button class="p-button primary" data-wa="confirm-resume">Confirmar retomada</button>');return;}busy=true;b.disabled=true;try{await act(action==='confirm-resume'?'resume':action,{confirmed:true});closeDialog();await load();}catch(err){toast(err.message,true);}finally{busy=false;b.disabled=false;}});
 document.addEventListener('submit',async e=>{if(!active||!['wa-send','wa-contact-form'].includes(e.target.id))return;e.preventDefault();if(busy||locked&&e.target.id==='wa-send')return;busy=true;const form=e.target,button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{if(form.id==='wa-contact-form'){const f=new FormData(form);const c=await act('contact',{phone:f.get('phone'),name:f.get('name'),consent:f.get('consent')==='on',evidence:f.get('evidence')});phone=c.phone;closeDialog();}else{draft.requestId||=crypto.randomUUID();const t=data.templates.find(t=>t.name===draft.template);let r;try{r=await act('send',{text:draft.text,assetId:draft.asset?.id,requestId:draft.requestId,template:t?.name,language:t?.language,parameters:draft.parameters});}catch(err){locked=true;throw err;}if(['uncertain','sending'].includes(r.state)){locked=true;toast('Envio sem confirmação. Confira antes de repetir.',true);}else if(r.state==='failed'){draft.requestId=null;toast(r.error||'A Meta recusou o envio.',true);}else{draft={text:'',template:'',parameters:[],asset:null,requestId:null};toast('Mensagem aceita pela Meta. Acompanhe a entrega na conversa.');}}}catch(err){toast(err.message,true);}finally{busy=false;await load();}});
 function mount(view){active=view==='whatsapp';++epoch;clearInterval(poll);if(active){load();poll=setInterval(()=>{if(active&&!busy&&!document.querySelector('#editor')?.open)load(true);},15000);}}
 return {page,mount};
}
